/**
 * Source pane: the LaTeX source of the document (what its .tex file contains), generated by the
 * server from the live editor state. It is editable — "Apply" sends the edited source back; the
 * server parses it and replaces the document content through the normal collaborative channel
 * (as a diff, so paragraphs that did not change keep their identity).
 */
import { useEffect, useRef, useState } from 'preact/hooks';
import type { EditorView } from 'prosemirror-view';
import type * as Y from 'yjs';
import { writeLyx, pmToLyxBody } from '@overlyx/core';
import { api } from '../api';

export interface SourceTarget { view: EditorView; ydoc: Y.Doc; docId: string }

function metaOf(ydoc: Y.Doc) {
  const m = ydoc.getMap<string>('meta');
  const parse = (k: string, def: unknown) => { try { const v = m.get(k); return v ? JSON.parse(v) : def; } catch { return def; } };
  return {
    preamble: parse('preamble', []) as string[],
    format: parse('format', 643) as number,
    header: parse('header', []) as string[],
    trailer: parse('trailer', []) as string[],
  };
}

/**
 * The document in LyX's file format, generated in the browser (no server needed): the fallback
 * for keeping unsynced offline edits when the server cannot store them — the file can be imported
 * into a project again.
 */
export function generateLyx(t: SourceTarget): string {
  const meta = metaOf(t.ydoc);
  return writeLyx({ preamble: ['#LyX 2.5 created this file. For more info see https://www.lyx.org/'], format: meta.format, header: { lines: meta.header }, body: pmToLyxBody(t.view.state.doc), trailer: meta.trailer });
}

export function SourcePane({ target, tick, onNotify }: { target: SourceTarget | null; tick: number; selTick?: number; onNotify: (msg: string, kind?: 'info' | 'error') => void }) {
  const [text, setText] = useState('');
  const [dirty, setDirty] = useState(false);
  const [busy, setBusy] = useState(false);
  const ta = useRef<HTMLTextAreaElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const seq = useRef(0);

  const load = async () => {
    if (!target) return;
    const my = ++seq.current;
    try {
      const t = await api.texText(target.docId);
      if (my === seq.current) setText(t);
    } catch (e) { if (my === seq.current) setText('% could not generate source: ' + (e as Error).message); }
  };

  // regenerate the source when the document changes (unless the user is editing the source)
  useEffect(() => {
    if (!target || dirty) return;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => { void load(); }, 700);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [target?.docId, tick, dirty]);

  const apply = async () => {
    if (!target) return;
    setBusy(true);
    try {
      const r = await api.applySource(target.docId, text);
      setDirty(false);
      onNotify(r.warnings.length ? `Source applied (${r.warnings.length} warning${r.warnings.length > 1 ? 's' : ''}: ${r.warnings[0]})` : 'Source applied to the document');
    } catch (e) {
      onNotify('Cannot apply source: ' + (e as Error).message, 'error');
    }
    setBusy(false);
  };
  const revert = () => { setDirty(false); void load(); };

  const name = target?.docId.split('/').pop() ?? '';
  return (
    <div class="source-pane">
      <div class="bar">
        <span class="small-btn active" title="The LaTeX source of the document (its .tex file)">LaTeX</span>
        <span class="name" title={target?.docId}>{name}</span>
        <span style="flex:1" />
        {dirty && <button class="small-btn primary" disabled={busy} onClick={() => void apply()} title="Parse the edited source and replace the document">{busy ? '…' : 'Apply'}</button>}
        {dirty && <button class="small-btn" onClick={revert}>Revert</button>}
        {!dirty && <button class="small-btn" onClick={() => void load()} title="Regenerate from the editor">Refresh</button>}
        <button class="small-btn" onClick={() => { void navigator.clipboard?.writeText(text); }} title="Copy to clipboard">Copy</button>
      </div>
      <textarea ref={ta} class="source" spellcheck={false} value={text} onInput={e => { setText((e.target as HTMLTextAreaElement).value); setDirty(true); }} onKeyDown={e => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && dirty) { e.preventDefault(); void apply(); } }} />
      <div class="hint">{dirty ? 'Edited — Apply (Ctrl+Enter) replaces the document with this source.' : 'The LaTeX source of the document as it is saved. Edit and apply, or copy.'}</div>
    </div>
  );
}
